with filtered as (select *, quantity + unit_price as line_total, least(unit_price, quantity) as least_unit_price_quantity from order_items where quantity <= 8) select product_id, case when least_unit_price_quantity >= 78 then 'LARGE' else 'SMALL' end as least_unit_price_quantity_tier, corr(quantity, unit_price) as corr_quantity_unit_price, bit_or(quantity) as quantity_bit_or, max(quantity) as max_quantity, min(line_total) as min_line_total, count(*) as num_rows from filtered group by product_id, case when least_unit_price_quantity >= 78 then 'LARGE' else 'SMALL' end having bit_or(quantity) < 1 order by corr_quantity_unit_price asc;
